describe('Internal Links Open in Same Tab', () => {
  beforeEach(() => {
    cy.visit('/pages/home');
  });

  it('should open internal links in the same tab', () => {
    // Verify the page loads successfully
    cy.get('[data-testid="home-page"]').should('be.visible');

    // Click on an internal link
    cy.get('[data-testid="internal-link-about"]').click();

    // Verify navigation to the correct page
    cy.url().should('include', '/pages/about');

    // Verify the page content is visible
    cy.get('[data-testid="about-page-title"]').should('be.visible');
    cy.get('[data-testid="about-page-title"]').should('contain', 'About Us');

    // Verify the same tab is used (no new window/tab opened)
    cy.window().then((win) => {
      expect(win.opener).to.equal(null);
    });
  });

  it('should handle internal links with no target attribute and open in same tab', () => {
    // Verify the page loads successfully
    cy.get('[data-testid="home-page"]').should('be.visible');

    // Click on an internal link without a target attribute
    cy.get('[data-testid="internal-link-contact"]').click();

    // Verify navigation to the correct page
    cy.url().should('include', '/pages/contact');

    // Verify the page content is visible
    cy.get('[data-testid="contact-page-title"]').should('be.visible');
    cy.get('[data-testid="contact-page-title"]').should('contain', 'Contact');

    // Verify the same tab is used
    cy.window().then((win) => {
      expect(win.opener).to.equal(null);
    });
  });
});
